#!/usr/bin/env bash
# GENERATED BY GALAXY - safe to customize, Galaxy will not overwrite it.
#
# One branch per brand (branch name = brand name from token_pipeline/brands).
# Each brand branch = default branch + src/app/theme/galaxy_brand.dart locked to the brand.
set -euo pipefail

APP_ROOT="apps/demo_app"
BRAND_FILE="${APP_ROOT:+$APP_ROOT/}lib/src/app/theme/galaxy_brand.dart"
BRANDS_DIR="token_pipeline/brands"
DEFAULT_BRANCH="${DEFAULT_BRANCH:-$(git rev-parse --abbrev-ref HEAD)}"

if [ ! -d "$BRANDS_DIR" ]; then
  echo "No brands found in $BRANDS_DIR - nothing to do."
  exit 0
fi

git config user.name "galaxy-bot"
git config user.email "galaxy-bot@users.noreply.github.com"
git fetch origin --prune

write_brand_file() {
  mkdir -p "$(dirname "$BRAND_FILE")"
  cat > "$BRAND_FILE" <<DART
// galaxy-brand-file
// Which brand this branch builds.
//   ''       -> demo build: every brand is selectable from the in-app switcher.
//   'ocean'  -> white-label build locked to the "ocean" brand.
// Galaxy never overwrites this file; the brand-branch workflow sets it.
const String galaxyLockedBrand = '$1';
DART
}

for file in "$BRANDS_DIR"/*.json; do
  [ -e "$file" ] || continue
  brand="$(basename "$file" .json)"
  [ "$brand" = "$DEFAULT_BRANCH" ] && continue

  if git show-ref --verify --quiet "refs/remotes/origin/$brand"; then
    git checkout -q -B "$brand" "origin/$brand"
    if ! git merge --no-edit "origin/$DEFAULT_BRANCH"; then
      git merge --abort || true
      echo "::warning::Could not merge $DEFAULT_BRANCH into $brand (conflict). Resolve it manually."
      continue
    fi
  else
    git checkout -q -B "$brand" "origin/$DEFAULT_BRANCH"
  fi

  write_brand_file "$brand"
  git add "$BRAND_FILE"

  if ! git diff --cached --quiet; then
    git commit -q -m "chore: build $brand brand [skip ci]"
  fi

  git push origin "$brand"
  echo "Brand branch '$brand' is up to date."
done

git checkout -q "$DEFAULT_BRANCH"
